.slider__container {
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  gap: var(--padding-s);
  width: 100%;
  height: 100%;

  .slides {
    position: relative;
    width: 100%;
    height: 100%;
    min-height: 0;
    display: block;
    overflow: hidden;
    isolation: isolate;

    .slide {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      justify-items: center;
      align-items: center;
      place-items: center;
      display: grid;
      opacity: 0;
      pointer-events: none;
      background-color: transparent;
      overflow: hidden;
      cursor: pointer;
      transition:
        opacity 220ms ease,
        transform 260ms ease,
        filter 260ms ease;

      &:empty {
        opacity: 0;
      }

      @media screen and (max-width: 60em) {
        height: 100%;
      }

      &.is-current {
        opacity: 1;
        pointer-events: auto;
        z-index: 3;
        transform: translate3d(0, 0, 0) scale(1);
      }

      &.is-previous {
        opacity: 0.85;
        z-index: 2;
        transform: translate3d(0.85rem, 0.85rem, 0) scale(0.985);
        filter: grayscale(1) brightness(0.82) contrast(0.95);
      }

      &.is-oldest {
        opacity: 0.2;
        z-index: 1;
        transform: translate3d(0, 0, 0) scale(1.03);
        filter: grayscale(1) brightness(0.45) contrast(0.9);
      }

      .slide__media {
        width: min(100%, 72rem);
        height: clamp(22rem, 72vh, 52rem);
        justify-self: center;
        align-self: center;
        margin: 0 auto;
        display: grid;
        place-items: center;
        padding: clamp(0.5rem, 2vw, 1.5rem);

        @media screen and (max-width: 60em) {
          width: 100%;
          height: clamp(18rem, 60vh, 36rem);
          padding-inline: 0;
        }
      }

      img,
      video {
        display: block;
        width: 100%;
        height: 100%;
        max-width: 100%;
        max-height: 100%;
        margin: 0 auto;
        object-fit: contain;
        object-position: center;
      }
    }
  }

  .info__wrapper {
    display: none;
  }

  .slide__info {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 1rem;

    .slide__title {
      display: block;
      text-transform: capitalize;
    }

    .slide__count {
      color: var(--muted-color);
      white-space: nowrap;
    }
  }

  .slide__description {
    display: block;
    color: var(--muted-color);
    max-width: 36rem;
  }
}

.slider__container--single {
  width: min(100%, 72rem);
  min-height: calc(100vh - var(--m));
  margin: 0 auto;

  .slide {
    &.is-current {
      opacity: 1;
      transform: translate3d(0, 0, 0) scale(1);
    }

    &.is-previous {
      opacity: 0.3;
      transform: translate3d(0, 0, 0) scale(1.015);
      filter: grayscale(1) brightness(0.6) contrast(0.9);
    }

    &.is-oldest {
      opacity: 0.16;
      transform: translate3d(0, 0, 0) scale(1.04);
      filter: grayscale(1) brightness(0.42) contrast(0.9);
    }
  }
}

